<?php require_once __DIR__.'/includes/bootstrap.php';$redirect=return_url($_GET['redirect']??'dashboard.php');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$name=trim($_POST['username']??'');$pass=(string)($_POST['password']??'');if(strlen($name)<3||strlen($pass)<8)$error='Use at least 3 characters for the username and 8 for the password.';else try{$s=$pdo->prepare('INSERT INTO users(username,password,role) VALUES(?,?,?)');$s->execute([$name,password_hash($pass,PASSWORD_DEFAULT),'user']);header('Location: login.php?redirect='.rawurlencode($redirect));exit;}catch(PDOException $e){$error='That username is already in use.';}}$pageTitle='Create account';require __DIR__.'/includes/header.php';?><main><section class="section" style="max-width:520px;margin:auto"><article class="panel"><h1>Create an account</h1><?php if($error):?><div class="notice"><?=h($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf_token" value="<?=csrf()?>"><input type="hidden" name="redirect" value="<?=h($redirect)?>"><label>Username</label><input name="username" required minlength="3"><label>Password</label><input name="password" type="password" required minlength="8"><button class="button" style="margin-top:18px">Create account</button></form></article></section></main><?php require __DIR__.'/includes/footer.php';?>
